package main

// Help text layout follows Python argparse at 80 columns.
var helpTexts = map[string]struct{ usage, body string }{
	"":                                      {"usage: airpods [-h] [--version] [--serial SERIAL] [--json] [--debug]\n               {help,completion,list,status,settings,get,set,audio,game,nearby,perf,info,hearing,hardware,experimental,reconnect,connect,pair,pair-phone,disconnect,reconnect-policy,firmware,diag} ...\n", "\nControl AirPods through the dongle's existing USB HID interface.\n\npositional arguments:\n  {help,completion,list,status,settings,get,set,audio,game,nearby,perf,info,hearing,hardware,experimental,reconnect,connect,pair,pair-phone,disconnect,reconnect-policy,firmware,diag}\n    help                show commands or help for a setting\n    completion          print a shell completion script\n    list                list attached dongles; works with none attached\n    status              show connection, codec and batteries without changing\n                        settings\n    settings            list readable setting values and their report ages\n    get                 read one reported setting\n    set                 change one setting and wait for device confirmation\n    audio               show the audio profile, or change it with audio set\n    game                turn game mode on or off\n    nearby              search for the AirPods by signal strength for a\n                        bounded time\n    perf                show the dongle performance counters\n    info                show model, firmware and serial, and what the model can\n                        do\n    hearing             read Hearing Aid and Media Assist, or change them\n    hardware            read saved hardware results and data, or run the in-case\n                        check\n    experimental        transparency, loud sound reduction, EQ and rename; needs\n                        --experimental\n    reconnect           ask the dongle to reconnect to its AirPods; confirms\n                        only that the dongle took the request\n    connect             connect the AirPods and confirm that the dongle owns\n                        their audio\n    pair                start pairing new AirPods; refused while audio or a\n                        phone is in use\n    pair-phone          open the dongle's phone pairing window\n    disconnect          disconnect AirPods but keep them paired; needs dongle\n                        firmware 0.1.59 or newer\n    reconnect-policy    read or save whether the dongle reconnects by itself;\n                        needs dongle firmware 0.1.63 or newer\n    firmware            show the version of the dongle firmware; needs firmware\n                        with the version report\n    diag                capture read-only audio diagnostics as JSON Lines\n\noptions:\n  -h, --help            show this help message and exit\n  --version             show the version and exit\n  --serial SERIAL       select one Pico by its USB serial; required when\n                        multiple dongles are attached\n  --json                print status, settings, get, list, info and other reads\n                        as JSON\n  --debug               print request channel traffic to stderr: sizes and codes,\n                        no addresses or serials\n\nClose NTPods or other HID control clients before using settings commands.\n"},
	"help":                                  {"usage: airpods help [-h] [topic]\n", "\npositional arguments:\n  topic       command or setting name\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"completion":                            {"usage: airpods completion [-h] {bash,zsh,fish,powershell}\n", "\npositional arguments:\n  {bash,zsh,fish,powershell}\n\noptions:\n  -h, --help            show this help message and exit\n"},
	"list":                                  {"usage: airpods list [-h] [--serials]\n", "\noptions:\n  -h, --help  show this help message and exit\n  --serials   print only the USB serials, one per line, without opening any\n              dongle\n"},
	"status":                                {"usage: airpods status [-h] [--details]\n", "\noptions:\n  -h, --help  show this help message and exit\n  --details   also show the dongle serial, AirPods address, noise control and\n              what is in use, and battery ages and charging\n"},
	"settings":                              {"usage: airpods settings [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"get":                                   {"usage: airpods get [-h]\n                   {mode,microphone,ear-detection,one-bud-anc,conversation-awareness,personalized-volume,allow-off,pause-when-asleep,case-sounds,optimized-charging,volume-swipe,press-speed,hold-duration,swipe-duration,call-controls,crown-direction,tone-volume,case-volume,adaptive-strength,hold-modes,hold-actions,connect-automatically,allow-auto-connect,en352-protection,gain-swipe}\n", "\npositional arguments:\n  {mode,microphone,ear-detection,one-bud-anc,conversation-awareness,personalized-volume,allow-off,pause-when-asleep,case-sounds,optimized-charging,volume-swipe,press-speed,hold-duration,swipe-duration,call-controls,crown-direction,tone-volume,case-volume,adaptive-strength,hold-modes,hold-actions,connect-automatically,allow-auto-connect,en352-protection,gain-swipe}\n\noptions:\n  -h, --help            show this help message and exit\n"},
	"set":                                   {"usage: airpods set [-h]\n                   {mode,microphone,ear-detection,one-bud-anc,conversation-awareness,personalized-volume,allow-off,pause-when-asleep,case-sounds,optimized-charging,volume-swipe,press-speed,hold-duration,swipe-duration,call-controls,crown-direction,tone-volume,case-volume,adaptive-strength,hold-modes,hold-actions,connect-automatically,allow-auto-connect,en352-protection,gain-swipe}\n                   value\n", "\npositional arguments:\n  {mode,microphone,ear-detection,one-bud-anc,conversation-awareness,personalized-volume,allow-off,pause-when-asleep,case-sounds,optimized-charging,volume-swipe,press-speed,hold-duration,swipe-duration,call-controls,crown-direction,tone-volume,case-volume,adaptive-strength,hold-modes,hold-actions,connect-automatically,allow-auto-connect,en352-protection,gain-swipe}\n  value                 named value; use help SETTING to see accepted values\n\noptions:\n  -h, --help            show this help message and exit\n"},
	"audio":                                 {"usage: airpods audio [-h] {set} ...\n", "\npositional arguments:\n  {set}\n    set       change codec, bitrate or variable bitrate\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"audio set":                             {"usage: airpods audio set [-h] [--codec {auto,sbc,aac,aac-eld}]\n                         [--bitrate BITRATE] [--variable {on,off}]\n", "\noptions:\n  -h, --help            show this help message and exit\n  --codec {auto,sbc,aac,aac-eld}\n                        without this flag the requested codec stays\n  --bitrate BITRATE     default, or for aac 96000, 128000, 174000, 192000,\n                        220000, or for aac-eld 128000, 174000, 192000, 220000,\n                        256000\n  --variable {on,off}   variable bitrate; aac-eld only\n"},
	"game":                                  {"usage: airpods game [-h] {on,off}\n", "\npositional arguments:\n  {on,off}\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"nearby":                                {"usage: airpods nearby [-h] [--seconds SECONDS]\n", "\noptions:\n  -h, --help         show this help message and exit\n  --seconds SECONDS  how long to search, 1..300 (default 30)\n"},
	"perf":                                  {"usage: airpods perf [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"info":                                  {"usage: airpods info [-h] [--show-serial] [--capabilities]\n", "\noptions:\n  -h, --help      show this help message and exit\n  --show-serial   print the AirPods' serial number, which is hidden by default\n  --capabilities  list what the model catalog says about this model\n"},
	"hearing":                               {"usage: airpods hearing [-h] {status,aid,media-assist,recover,profile} ...\n", "\nHearing Aid and Media Assist change how sound is presented, including how loud\nit is. They have not been verified on real AirPods. See docs/CLI.md.\n\npositional arguments:\n  {status,aid,media-assist,recover,profile}\n    status              read the modes; writes nothing\n    aid                 turn Hearing Aid on or off\n    media-assist        turn Media Assist on or off\n    recover             after an unconfirmed change: read the modes, and with\n                        --off turn one off\n    profile             show the stored hearing profile, or apply a new one\n\noptions:\n  -h, --help            show this help message and exit\n"},
	"hearing status":                        {"usage: airpods hearing status [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"hearing aid":                           {"usage: airpods hearing aid [-h] [--yes] {on,off}\n", "\npositional arguments:\n  {on,off}\n\noptions:\n  -h, --help  show this help message and exit\n  --yes       do not ask before turning it on\n"},
	"hearing media-assist":                  {"usage: airpods hearing media-assist [-h] [--yes] {on,off}\n", "\npositional arguments:\n  {on,off}\n\noptions:\n  -h, --help  show this help message and exit\n  --yes       do not ask before turning it on\n"},
	"hearing recover":                       {"usage: airpods hearing recover [-h] [--off {hearing-aid,media-assist}]\n", "\nWithout --off this only reads the modes and says what to do.\n\noptions:\n  -h, --help            show this help message and exit\n  --off {hearing-aid,media-assist}\n                        turn this mode off\n"},
	"hearing profile":                       {"usage: airpods hearing profile [-h] {show,apply} ...\n", "\npositional arguments:\n  {show,apply}\n    show        read the stored profile; writes nothing\n    apply       change the stored profile, after showing what changes\n\noptions:\n  -h, --help    show this help message and exit\n"},
	"hearing profile show":                  {"usage: airpods hearing profile show [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"hearing profile apply":                 {"usage: airpods hearing profile apply [-h] [--file FILE] [--left LEFT]\n                                     [--right RIGHT]\n                                     [--amplification AMPLIFICATION]\n                                     [--balance BALANCE] [--tone TONE]\n                                     [--conversation-boost {on,off}] [--yes]\n", "\nFlags replace what the file says. What neither gives stays as stored.\n\noptions:\n  -h, --help            show this help message and exit\n  --file FILE           a JSON file; see docs/CLI.md\n  --left LEFT           8 comma separated values, 0 to 90 dB HL, for 250, 500,\n                        1000, 2000, 3000, 4000, 6000 and 8000 Hz\n  --right RIGHT         the same for the right ear\n  --amplification AMPLIFICATION\n                        the mean gain of both ears, -1.5 to 1.5\n  --balance BALANCE     right minus left gain, -3 to 3; no ear may leave -1.5 to\n                        1.5\n  --tone TONE           -1 to 1, for both ears\n  --conversation-boost {on,off}\n                        for both ears\n  --yes                 do not ask before applying\n"},
	"hardware":                              {"usage: airpods hardware [-h] {status,data,check} ...\n", "\nThese are results from the AirPods' own self-check, not a medical or repair\ndiagnosis.\n\npositional arguments:\n  {status,data,check}\n    status             read the saved result for each ear\n    data               read hearing test mode, dosimetry sensitivity and volume\n                       curve, as raw values\n    check              run the in-case check and wait for its result\n\noptions:\n  -h, --help           show this help message and exit\n"},
	"hardware status":                       {"usage: airpods hardware status [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"hardware data":                         {"usage: airpods hardware data [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"hardware check":                        {"usage: airpods hardware check [-h] [--buds-in-case]\n", "\nCtrl-C stops the waiting, not the check: it cannot be cancelled.\n\noptions:\n  -h, --help      show this help message and exit\n  --buds-in-case  confirm that both AirPods are in the open case, instead of\n                  being asked\n"},
	"experimental":                          {"usage: airpods experimental [-h] [--experimental]\n                            {transparency,loud-sound-reduction,eq,rename} ...\n", "\nNone of these has run on real AirPods, and they may not work through the dongle.\nEach one needs --experimental, before or after its subcommand.\n\npositional arguments:\n  {transparency,loud-sound-reduction,eq,rename}\n    transparency        read or change Custom Transparency\n    loud-sound-reduction\n                        read or change Loud Sound Reduction\n    eq                  read the AirPods' EQ, or change it and wait for their\n                        report\n    rename              send a new AirPods name; the AirPods never confirm it\n\noptions:\n  -h, --help            show this help message and exit\n  --experimental        run it, although it may not work through the dongle\n"},
	"experimental transparency":             {"usage: airpods experimental transparency [-h] {show,set} ...\n", "\npositional arguments:\n  {show,set}\n    show      read it; writes nothing\n    set       change it and read it back\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"experimental transparency show":        {"usage: airpods experimental transparency show [-h] [--experimental]\n", "\noptions:\n  -h, --help      show this help message and exit\n  --experimental  run it, although it may not work through the dongle\n"},
	"experimental transparency set":         {"usage: airpods experimental transparency set [-h] [--experimental]\n                                             [--enabled {on,off}]\n                                             [--ear {left,right,both}]\n                                             [--amplification AMPLIFICATION]\n                                             [--tone TONE]\n                                             [--noise-reduction NOISE_REDUCTION]\n                                             [--conversation-boost {on,off}]\n", "\nWhat is not given stays as stored.\n\noptions:\n  -h, --help            show this help message and exit\n  --experimental        run it, although it may not work through the dongle\n  --enabled {on,off}\n  --ear {left,right,both}\n                        the ear the other flags apply to (default both)\n  --amplification AMPLIFICATION\n                        -1 to 2\n  --tone TONE           -1 to 1\n  --noise-reduction NOISE_REDUCTION\n                        ambient noise reduction, 0 to 1\n  --conversation-boost {on,off}\n"},
	"experimental loud-sound-reduction":     {"usage: airpods experimental loud-sound-reduction [-h] {get,set} ...\n", "\npositional arguments:\n  {get,set}\n    get       read it; writes nothing\n    set       change it and read it back\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"experimental loud-sound-reduction get": {"usage: airpods experimental loud-sound-reduction get [-h] [--experimental]\n", "\noptions:\n  -h, --help      show this help message and exit\n  --experimental  run it, although it may not work through the dongle\n"},
	"experimental loud-sound-reduction set": {"usage: airpods experimental loud-sound-reduction set [-h] [--experimental] {on,off}\n", "\npositional arguments:\n  {on,off}\n\noptions:\n  -h, --help      show this help message and exit\n  --experimental  run it, although it may not work through the dongle\n"},
	"experimental eq":                       {"usage: airpods experimental eq [-h] {show,set} ...\n", "\npositional arguments:\n  {show,set}\n    show      read it; writes nothing\n    set       change it and wait for the AirPods to report it\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"experimental eq show":                  {"usage: airpods experimental eq show [-h] [--experimental]\n", "\noptions:\n  -h, --help      show this help message and exit\n  --experimental  run it, although it may not work through the dongle\n"},
	"experimental eq set":                   {"usage: airpods experimental eq set [-h] [--experimental] [--enabled {on,off}]\n                                   [--low LOW] [--mid MID] [--high HIGH]\n", "\nWhat is not given stays as the AirPods reported it. Only a new EQ report with\nexactly these values confirms the change.\n\noptions:\n  -h, --help          show this help message and exit\n  --experimental      run it, although it may not work through the dongle\n  --enabled {on,off}\n  --low LOW           0 to 100\n  --mid MID           0 to 100\n  --high HIGH         0 to 100\n"},
	"experimental rename":                   {"usage: airpods experimental rename [-h] [--experimental] name\n", "\nThe AirPods never confirm this, so the result only ever says sent. The old name\nmay show until they reconnect.\n\npositional arguments:\n  name            1 to 64 bytes of UTF-8, with no control characters\n\noptions:\n  -h, --help      show this help message and exit\n  --experimental  run it, although it may not work through the dongle\n"},
	"reconnect":                             {"usage: airpods reconnect [-h]\n", "\nThe plain reconnect request: the dongle takes it and connects when it can. It\ndoes not wait for the AirPods; airpods connect does.\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"connect":                               {"usage: airpods connect [-h]\n", "\nConnects the saved AirPods through the routing handover and waits up to 5 s for\nthe dongle to own their audio. On dongle firmware before 0.1.59 it sends the\nreconnect request instead, which is not confirmed.\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"pair":                                  {"usage: airpods pair [-h] [--yes]\n", "\nThis erases the saved pairing. It asks first; without a terminal it needs --yes.\n\noptions:\n  -h, --help  show this help message and exit\n  --yes       do not ask\n"},
	"pair-phone":                            {"usage: airpods pair-phone [-h]\n", "\noptions:\n  -h, --help  show this help message and exit\n"},
	"disconnect":                            {"usage: airpods disconnect [-h]\n", "\nReleases the AirPods and keeps them paired. The dongle then holds them off until\nconnect, reconnect, a press of its button or a restart of the dongle.\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"firmware":                              {"usage: airpods firmware [-h]\n", "\nShows the version of the firmware the dongle runs. It changes nothing. Dongle\nfirmware without the version report refuses it.\n\noptions:\n  -h, --help  show this help message and exit\n"},
	"diag":                                  {"usage: airpods diag [-h] [--version] [--seconds SECONDS] [--serial SERIAL]\n                    [--output OUTPUT] [--legacy] [--inspect] [--phone]\n                    [--radio] [--no-trace] [--replace]\n", "\nRead-only Pico audio diagnostics over Windows HID or Linux hidraw. No\ncompanion app is needed. Output is JSON Lines; use --output to retain a\nbounded capture locally.\n\noptions:\n  -h, --help         show this help message and exit\n  --version          show the version and exit\n  --seconds SECONDS\n  --serial SERIAL    Require this Pico serial\n  --output OUTPUT    JSONL destination (default stdout)\n  --legacy           Only existing feature 5/9 snapshots\n  --inspect          Include signal levels and the latest submitted AAC-ELD\n                     frame\n  --phone            Include phone input queue and decoder counters\n  --radio            Only cached radio and adaptive-bitrate readings, every\n                     two seconds\n  --no-trace         Leave out the timing counters and recent events; unlike\n                     --legacy it combines with --inspect and --phone\n  --replace          Overwrite the --output file if it exists\n"},
	"reconnect-policy":                      {"usage: airpods reconnect-policy [-h] [{manual,auto}]\n", "\nWithout a policy this reads it. manual, the default: the dongle connects to the\nAirPods only when asked. auto: it also reconnects by itself whenever they are\nnot connected, which can take them from another device. The dongle saves only\nwhile idle.\n\npositional arguments:\n  {manual,auto}  omit to read; auto may take the AirPods from another device\n\noptions:\n  -h, --help     show this help message and exit\n"},
}
